quests[44471] = { id = 44471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Sight", description = "Though young King Anduin is a noble soul, he may lack the conviction of his father. The Alliance needs a leader who will do what needs to be done. The Legion will strike at the first hint of weakness.\n\nEven now, I sense something amiss, {name}. I fear that not all is as it seems.\n\nQuickly, use your Spectral Sight. We must know if there are foes among us!", progress = "Time is precious.", completion = "Of course the Legion would try to infiltrate this funeral. Having all the leaders of the Alliance gathered in one place at one time... it is too tasty a target for the demons to resist!", objectives = "Use your Spectral Sight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44472] = { id = 44472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: When There's a Will, There's a Way 5" }
quests[44473] = { id = 44473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Weapon of the Alliance", description = "At first I was unsure whether it was wise to allow the Illidari inside the city. But you may have just saved all our lives.\n\nYou may establish a camp in the Mage Quarter. The Alliance will have need of your skills if we are to face the Legion.\n\nMake no mistake though. Should your kind give in to the fel energies you toy with, we will treat you like the demons you are becoming.", completion = "I trust the young king is safe.\n\nWe have more work ahead of us, {class}. Much more.", objectives = "Meet with the Illidari in the Mage Quarter of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44474] = { id = 44474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Following In His Footsteps 1" }
quests[44475] = { id = 44475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Following In His Footsteps 2" }
quests[44476] = { id = 44476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Following In His Footsteps 3" }
quests[44477] = { id = 44477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Following In His Footsteps 4" }
quests[44478] = { id = 44478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Following In His Footsteps 5" }
quests[44479] = { id = 44479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravencrest's Legacy", description = "Years later, as the War of the Ancients raged on and the Burning Legion's grip upon this world took hold, Illidan would meet a military leader known as Kur'talos Ravencrest. He too would see the potential within Illidan, eventually promoting him to captain of the Moon Guard: a powerful group of night elf sorcerers.\n\nWe must experience this memory in Black Rook Hold, located on the western shores of Val'sharah.", progress = "Without Light, the darkness cannot exist.", completion = "The line between good and evil is thin, and resides in a place where intention means little.\n\nIllidan wondered how those around him could be so blind to the threat of the Burning Legion. Fate is not without a sense of irony.", objectives = "Experience Ravencrest's Legacy at Black Rook Hold in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44480] = { id = 44480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In My Father's House", description = "Most mortals cannot comprehend the truth of the Legion. Those that recognize it, often refuse to accept its meaning. Such knowledge carries a weight that the mortal frame cannot bear. To sacrifice that much of ones self changes the soul.\n\nAmong your greatest heroes, a rare few understood that type of sacrifice. Let us witness it through Illidan's eyes.\n\nWe must go to Azshara, on the continent of Kalimdor.", progress = "The vessel is nearly ready to take on the soul.", completion = "Illidan sought out the truth and was blinded by what he saw. He was beginning to understand his destiny, but there was one final sacrifice that he had yet to make.", objectives = "Witness Illidan's Sacrifice in Azshara on the continent of Kalimdor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44481] = { id = 44481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destiny Unfulfilled", description = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.\n\nYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.\n\nWe must travel to Outland to experience Illidan's last memory.", progress = "When the vessel is prepared, we will seek out his soul.", completion = "I wept when I touched your consciousness in the Great Dark, mortal. For I saw his fall, and I saw you, your shadow casting a dark pall over his body. I felt hatred in your heart as it corrupted your mind.\n\nIt was not Light's Heart, but you, that needed preparation. Now you know truth. Are you prepared to do what must be done to save your world and all others?\n\nWhen the time is right, I will call upon you to begin the hunt for Illidan's soul.\n\nHis rebirth will be the story of your redemption.", objectives = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44482] = { id = 44482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruiting Ebon Knights", description = "Korgaz Deadaxe has been hard at work training a new generation of death knights.\n\nHe has done an excellent job culling the ranks of weakness. Those who have survived the trials of death knight training are ready to join the ranks of the Ebon Blade.\n\nKorgaz is waiting for you on the upper level. I suggest you speak with him at your soonest convenience.\n\nNew death knights will bolster our ranks and aid is in the war against the Burning Legion.", sourceObjective = "Speak to Korgaz Deadaxe.", sourceObjectiveStatus = "unverified-source-field" }
quests[44483] = { id = 44483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vendor Beckon Trigger - Druid" }
quests[44484] = { id = 44484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vendor Beckon Trigger - Druid" }
quests[44486] = { id = 44486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel-Ravaged Tome", description = "Much of the elven writing in the tome has been singed by fel fire.\n\nThe head of the curators in Dalaran is renowned for his restoration skills.  Perhaps he can treat the tome to bring it back to legibility.", progress = "Oh, what's this one now?", completion = "Ah, the burns can be reversed with the right alchemic tinctures.\n\nHow interesting.  A formal Darnassian writing style with... demonic affectations.\n\nI suspect I know who penned this.", objectives = "Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44487] = { id = 44487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waterlogged Tome", description = "In spite of its magical nature, the book has been damaged by water.\n\nThe head of the curators in Dalaran is renowned for his abilities.  Perhaps he can restore it.", progress = "What have we here?", completion = "I would recognize that handwriting anywhere.  This is our own Khadgar's journal!", objectives = "Bring the Waterlogged Tome to Robert Newhearth in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44488] = { id = 44488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Tome", description = "Much of the elven writing in the tome has been singed by fel fire.\n\nThe head of the curators in Dalaran is renowned for his restoration skills.  Perhaps he can treat the tome to bring it back to legibility.", progress = "Oh, what's this one now?", completion = "Foul magic wards these texts.\n\nMuch stronger than anything I've seen before, but nothing that can't be undone by our mages!", objectives = "Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44489] = { id = 44489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lyana Darksorrow", description = "<Your fellow Illidari, Lyana Darksorrow, floats captive in stasis in front of you; her soul slowly draining into the harvester crystal.>\n\n<In order to release her from stasis, you will need to destroy the soul harvester.>", completion = "{name}, you are a sight for sore eyes. You have my gratitude for releasing me.\n\nI do not know how long I have been held captive... but I sense an overwhelming number of demons nearby.\n\nI have much to do here. Care to join me?", objectives = "Destroy the Soul Harvester.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44490] = { id = 44490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimwing the Devourer", description = "You have my thanks for rescuing me from captivity, {name}.\n\nHowever, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion.\n\nBefore we can get to him, there is another that must be destroyed.\n\nGrimwing the Devourer is the strongest of the felbats. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears.\n\nThen, return to me with her head. My thirst for vengeance must be quenched.", progress = "What news do you bring of Grimwing the Devourer?", completion = "Grimwing was a formidable demon... I must say I am always impressed with your skill, {name}.\n\nThere are many more demons here to kill. It is good to be at your side once more.", objectives = "Slay Grimwing the Devourer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44491] = { id = 44491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar Collapse Scenario - Run Once" }
quests[44492] = { id = 44492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyline Apprentice", description = "Good work finding those additional leyline feeds.\n\nYou seem rather competent - for an outlander.\n\nAllow me to share with you a few secrets about the power of the leylines. This should help you in scavenging more ancient mana from the creatures around Suramar. A grisly task, I know - which is why I leave it to you!", completion = "Now listen closely.", objectives = "Speak with Arcanist Valtrois.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44493] = { id = 44493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyline Proficiency", description = "Our leyline feed grows stronger.\n\nThe more powerful our feed becomes, the more I learn about ancient mana itself.\n\nOf course, as my apprentice, you may reap the benefits of my discoveries. Listen well, and I will teach you how to extract power from your enemies more reliably.", completion = "Do your best to pick this up the first time - I do hate repeating myself.", objectives = "Speak with Arcanist Valtrois.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44495] = { id = 44495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyline Master", description = "You surprise me, outlander. During our first lesson about the ancient leylines, I half-expected you to be lost in daydreams of adventure, or treasure or... some such nonsense.\n\nBut you have proven an apt student.\n\nOur leyline feed has grown extremely powerful. Watching it grow has taught me a great deal about the arcane, and the nature of mana.\n\nI have one final lesson that will help you find even more ancient mana.", completion = "Perhaps there is hope for outlanders after all.", objectives = "Speak with Arcanist Valtrois.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44496] = { id = 44496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destiny Unfulfilled", description = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.\n\nYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.\n\nWe must travel to Outland to experience Illidan's last memory.", progress = "When the vessel is prepared, we will seek out his soul.", completion = "In the end, the denizens of Azeroth and Outland came to exact their vengeance upon Illidan. Though you did not strike a blow against him, you were complicit in his fall.\n\nI showed you Illidan's life so that you would understand why he fought and made the choices that he made. Yours was the vessel that needed preparation.\n\nIf the hatred and doubt in your heart has subsided, take your place at the side of the Light. Soon I will call upon you as we begin the hunt for Illidan's soul.", objectives = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44497] = { id = 44497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destiny Unfulfilled", description = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.\n\nYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.\n\nWe must travel to Outland to experience Illidan's last memory.", progress = "When the vessel is prepared, we will seek out his soul.", completion = "Forgive me, noble soul. I mislead you. Light's Heart was not the vessel that required preparation, it was yours.\n\nYou, who sacrificed everything for your world, and served your master dutifully until the end. These memories will serve to strengthen your resolve. Look to them when the dark temptation surrounds you and let them grant you the strength to resist and rise against the corrupters.\n\nWe will save Illidan and once more you will battle at the side of your master for the fate of all worlds.", objectives = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44498] = { id = 44498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterhoof Cleansing", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  The well is to the southeast, but be warned: whoever did this may still be there, laying in wait.\n\nThis may prove very dangerous, {name}.  Be careful...but do not let the defilers of our well escape.", objectives = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44499] = { id = 44499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowfang Tracking Quest" }
quests[44500] = { id = 44500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Author! Author!", description = "We've reviewed the tome recovered from Karazhan. Though we found references to the Pillars of Creation, one piece of crucial information was omitted from the book... where to find the artifacts.\n\nFortunately, we have access to an expert on the subject.\n\nThe author, Alodi, was the first Guardian of Tirisfal. His spirit is forever bound to the Forge of the Guardian, which has been hidden in our safekeeping. I think the time has come to call him forth.", progress = "Alodi's knowledge of the Pillars of Creation is crucial to our campaign against the Legion.", completion = "We may not have the exact location of the Pillars of Creation, but at least we know where to start. We'll explore every corner of the Broken Isles until they're recovered.\n\nThe Legion's attack is intensifying. We must prepare to move Dalaran to the Broken Isles!", objectives = "Tell Khadgar to begin the ritual to summon the spirit of Alodi, the first Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44501] = { id = 44501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
