quests[44543] = { id = 44543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Broken Shore", description = "This wind rider will take you to Broken Shore, {name}. May your weapon bring you many kills today.\n\nThe Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.", completion = "Glad to see you back on your feet, {name}. Many good soldiers who sailed for the Broken Shore were not so fortunate.", objectives = "Take the wind rider to the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44544] = { id = 44544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Earthen Ring", description = "At last, I've found you!\n\nI have a message from Advisor Sevel.\n\nThe Earthen Ring has need of you, Farseer. Please return to the Heart of Azeroth at your soonest convenience. Advisor Sevel is eagerly awaiting your return.", completion = "It is good that you are here, Farseer {name}. We have much to discuss.", objectives = "Speak with Advisor Sevel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44545] = { id = 44545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing the Assault", description = "<With this Pillar of Creation safely secured, it is time to take advantage of your momentum and continue onward after the next.>\n\n<You recall that your order has gathered information that would aid you in your journey - looking it over once more before setting off would be wise.>", completion = "<Your order's intel in hand, you are well-prepared for your next assault on the Broken Isles.>", objectives = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44546] = { id = 44546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just south of Shadowfang Keep in Silverpine Forest. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", objectives = "Kill 12 Crown Chemical Co. Employees and use Snagglebolt's Khorium Bomb to destroy a chemical wagon south of Shadowfang Keep in Silverpine Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44547] = { id = 44547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Isle Hopping", description = "<Victory in hand, you know there are still Pillars of Creation that must be recovered if the Legion is to be defeated once and for all.>\n\n<Your order has identified uncharted regions of the Broken Isles that still house the remaining Pillars - looking over the information would help focus your next effort.>", objectives = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44548] = { id = 44548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouring What Remains", description = "<Looking around the chamber, you know you are well on your way to gathering all of the Pillars of Creation, but your work is not yet complete.>\n\n<Your order has continued to scour the isles below for anything that might be useful - best to check in with them before embarking once more.>", objectives = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44549] = { id = 44549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of the Isles", description = "<Only one region remains from your order's carefully laid plan to assault the Broken Isles and gather the Pillars of Creation.>\n\n<Victory feels close, but studying your order's intelligence one last time couldn't hurt.>", objectives = "Review your remaining assault point on the Broken Isles at the Command Map in your Order Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44550] = { id = 44550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Called to Acherus", description = "Deathlord, your presence has been requested on Acherus.\n\nThe war against the Burning Legion rages on and the Knights of the Ebon Blade await further orders.\n\nPlease return to Acherus at your soonest convenience. Siouxsie the Banshee is awaiting your return.", completion = "You have arrived at last, Deathlord. We have much to discuss.", objectives = "Speak with Siouxsie the Banshee at Acherus: The Ebon Hold. You can use Death Gate to return there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44551] = { id = 44551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Capturing the Gateway 1" }
quests[44552] = { id = 44552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Capturing the Gateway 2" }
quests[44553] = { id = 44553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Capturing the Gateway 3" }
quests[44554] = { id = 44554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mythic Keystone Weekly Tracking Quest" }
quests[44555] = { id = 44555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar's Discovery", description = "Champion! Please come to the Violet Citadel immediately.\n\nI have made a discovery that I would like to share with you before the Council of Six.", completion = "Thank you for coming, {name}.", objectives = "Speak with Archmage Khadgar in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44556] = { id = 44556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan", description = "Karazhan is now in the hands of the Legion, {name}.\n\nThe fault is mine. In my haste to retrieve Alodi's book on the Pillars of Creation, the defenses I put in place to protect the tower were ramshackle at best. The Legion was quick to find a weakness.\n\nThanks to the time Sargeras spent controlling Medivh, he knows the tower's secrets as well as I do. Whatever the Dark Titan's plan is, we must do everything in our power to stop it.\n\nCome at once! I'll meet you outside Karazhan.", completion = "We have work to do!", objectives = "Meet Khadgar outside Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44557] = { id = 44557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finite Numbers", description = "It seems not all the protections I put in place have been defeated. The Legion isn't able to open portals inside or near the tower... at least, not yet.\n\nThey appear to be bringing reinforcements in through the catacombs running beneath Deadwind Pass. Disable them and you just might buy us the time we need to drive them out of Karazhan.", completion = "Well done! At least now most of the remaining demons we have to deal with are currently inside the tower.\n\nCouldn't be more than a thousand or two, I'm sure.", objectives = "Close 4 Portals and slay 20 Demons in Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44558] = { id = 44558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just south of Shadowfang Keep in Silverpine Forest. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", objectives = "Kill 12 Crown Chemical Co. Employees and use Snagglebolt's Khorium Bomb to destroy a chemical wagon south of Shadowfang Keep in Silverpine Forest, then return to Inspector Snip Snagglebolt in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44559] = { id = 44559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow the Recipe", description = "This seems to be part of a recipe for whatever concoction the Crown Chemical Company is cooking up. The other parts must be nearby.", completion = "Aha! With this we can start on an antidote for this awful mixture. Thank you for bringing this to me.", objectives = "Collect the other parts of the Crown Chemical Company's recipe, then return to Detective Snap Snagglebolt in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44560] = { id = 44560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow the Recipe", description = "This seems to be part of a recipe for whatever concoction the Crown Chemical Company is cooking up. The other parts must be nearby.", completion = "Aha! With this we can start on an antidote for this awful mixture. Thank you for bringing this to me.", objectives = "Collect the other parts of the Crown Chemical Company's recipe, then return to Inspector Snip Snagglebolt in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44561] = { id = 44561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seed of Hope", description = "Thalyssra was wise to send you in search of the arcan'dor, though she underestimates its power.\n\nShe will learn - as will the others.\n\nBut it will take time. And with hunger gnawing at their very souls, the Nightfallen will need your help to survive.", progress = "The arcan'dor needs time.", completion = "In the changing of seasons, the truth will be revealed.", objectives = "Reach Honored with The Nightfallen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44562] = { id = 44562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing Strong", progress = "Have you felt it? Change is on the wind.", completion = "We shall help the shal'dorei find harmony.", objectives = "Reach Revered with The Nightfallen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44563] = { id = 44563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redemption for the Fallen", description = "Soon the change of seasons will be upon us, and the Nightfallen will take command of their fate.\n\nYou have given them hope, and set them on the path to redemption. They need you now more than ever.\n\nWe all do.", progress = "There is much to be done.", completion = "Finally, my long lost brethren can return to this world. Elves belong beneath a starry sky - not a conjured one.\n\nThank you, {name}.", objectives = "Reach Exalted with The Nightfallen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44569] = { id = 44569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitor Volitix" }
quests[44570] = { id = 44570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Spires of Arak flame.", objectives = "Honor the Midsummer Bonfire in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44571] = { id = 44571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Talador flame.", objectives = "Honor the Midsummer Bonfire in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
