quests[44577] = { id = 44577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence or crushing our enemies into dust!\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Stormheim flame.", objectives = "Honor the Midsummer Bonfire in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
