quests[44636] = { id = 44636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building an Army", description = "We must keep our eyes on the future. There will come a time when we will need an army.\n\nWe've proven that the withered are not completely beyond redemption. They can be taught, and molded.\n\nI want you to be their combat trainer, {name}. Come with me. We can use the nearby ruins as an arena to hone their abilities.", objectives = "Speak with Thalyssra when you are ready to lead the withered in their first combat training mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
