quests[44659] = { id = 44659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Skipped The Intro Tracking Quest" }
quests[44663] = { id = 44663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Blink of an Eye", description = "<The entity speaks with the familiar voice of Archmage Khadgar.>\n\nAzeroth needs you, {name}!\n\nAfter scouring Ulduar and Karazhan for answers, we know the key to defeating the Legion: five ancient artifacts called the Pillars of Creation.\n\nTo find them, Dalaran must be moved to the Broken Isles. As our leader Jaina is... absent, Kalecgos of the blue dragonflight has offered the Kirin Tor his aid.\n\nThe Legion is assaulting our current position over Deadwind Pass. Hurry!", completion = "Ah, {name}, it's good to see you on your feet! The members of the Council of Six are recuperating from their ordeal.\n\nThe intensity of the teleportation spell can be disorienting. It seems you lost consciousness for a time, but at least you didn't awaken to find yourself stuck in a wall!\n\nDalaran has been relocated to the Broken Isles. From here, we will spearhead the effort to acquire the Pillars of Creation and drive the Legion from Azeroth once and for all!", objectives = "Witness the teleportation of Dalaran to the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44667] = { id = 44667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will of the Valarjar", description = "As we prepare to launch an attack on the Legion's own world, it is important to not give reprieve to our enemies in this one.\n\nAs your armies seek to secure enemy gateways, you would do well to return to the Broken Isles and carry on the battle against those who stand against you.", progress = "You've returned, {name}.", completion = "You've done well.  Our enemies tremble before you and your armies.", objectives = "Complete 10 World Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44669] = { id = 44669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vicious Whale Shark" }
quests[44670] = { id = 44670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broodmother Lizax" }
quests[44671] = { id = 44671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Muscle" }
quests[44672] = { id = 44672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Mana", description = "Without the Nightwell to feed upon, my comrades and I will have to live off the land itself.\n\nAncient mana from the underground leylines can reach the surface in many forms, most commonly as crystals or gems.\n\n<Thalyssra picks up a small stone and, whispering words of power, traces a rune upon it with her fingertip.>\n\nThis stone will glow when ancient mana is nearby. Please gather as much as possible! It will be a precious resource in the weeks to come.", progress = "We need all the ancient mana we can get. Make sure you know how to find it!", completion = "Keep a lookout for those crystal formations all over Suramar. We will need them.", objectives = "Gather from 3 Ancient Mana nodes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44673] = { id = 44673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Soraax" }
quests[44675] = { id = 44675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Rivantas" }
quests[44676] = { id = 44676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Llorian" }
