quests[44678] = { id = 44678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Mana Tutorial Chest B" }
quests[44679] = { id = 44679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Mana Tutorial Chest C" }
quests[44680] = { id = 44680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leading by Example", description = "We cannot let our current situation overshadow the Unseen Path's mission to protect the people of Azeroth.\n\nThere are many in this world who could use our help.\n\nAs our leader, you can set the example by aiding those in need.", completion = "You are an inspiration to us all, {name}.", objectives = "Complete 10 World Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44682] = { id = 44682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unparalleled Power", description = "Power is all around us, {name}, waiting to be harnessed.\n\nYou must venture out into the world and claim it for the council!\n\nWith our First wielding such unparalleled power, our enemies won't stand a chance.", completion = "The power within you grows, {name}. You will serve the council well.", objectives = "Complete 10 World Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44683] = { id = 44683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holding the Lines", description = "Karazhan sits upon a confluence of ley lines. It's why this location was chosen for the tower in the first place... a fact that has not escaped the Legion's notice.\n\nIf the demons are tapping into these lines of power, they must need their energy for something particularly menacing. You must cut off their access to the ley lines if we're to have a chance of retaking the tower, {name}.", completion = "The Legion's hold wanes. Our time to strike grows nearer.", objectives = "Secure the Eastern Ley Line and Western Ley Line beneath Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44684] = { id = 44684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption Runs Deep", description = "Everything the Legion touches is marred by fingerprints of their corruption. If I can study the traces of magic they leave behind, perhaps I can discern their plans for Karazhan.\n\nThis vial is specially reinforced to contain fel magic. If you bring me the essences of corrupted soil and water from near their portals, I believe we'll be closer to unraveling their scheme.", progress = "What have we here?", completion = "Every bit contains an essence of sorts - one we can study to learn things about the magic wielder and ways to manipulate their magic for... other purposes.", objectives = "Recover an Essence of Corrupted Soil and an Essence of Corrupted Water from the caverns beneath Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44685] = { id = 44685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Ramparts", description = "With the ley lines protected we must move to secure the tower's perimeter.\n\nAround the tower are several locations where corruption continues to run rampant. Seek out these locations and secure them with these wards.\n\nWith the progress we've made so far, bolstering our defenses should keep the remaining Legion's forces at bay just long enough for us to discover who's behind their efforts.", progress = "Has the tower been secured?", completion = "You've bought us precious time.", objectives = "Plant the Wards at the Eastern, Southern and Northern locations around the tower in Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44686] = { id = 44686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thought Collection", description = "While I examine these samples further, I ask that you seek out one of our patrols in the structure to the north. It appears they've captured one of the demons.\n\nGo, interrogate it. Find out anything you can. And hurry! I'm afraid time is no longer an ally.", progress = "Has it been handled, {name}?", completion = "This information is just what we needed.", objectives = "Interrogate the Captured Wyrmtongue in the structure just north of the tower in Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44689] = { id = 44689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of the Tirisgarde", description = "The Tirisgarde has received requests from across the Broken Isles for aid in fighting the Burning Legion. While we will continue pursuing Archmage Vargoth, we cannot forget that our primary mission is to repel the demons and protect Azeroth.", progress = "Azeroth will burn without our help.", completion = "Well done, conjuror. With heroes like you at the helm, the Tirisgarde is a force to be reckoned with!", objectives = "Complete 10 World Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44690] = { id = 44690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thirst For Blood", progress = "Blood is the fountain of life and the fuel of my creations. Unfortunately, Deathlord, my supply is running low and the quality as of late has been disappointing at best.\n\nIf my undead offspring are to reach their full potential, I will need pure blood of the highest quality. Bring me the Blood of Sargeras and I will use it to fuel my finest creations!", completion = "At last, I have enough Blood of Sargeras to fuel my creations! You will see, Deathlord, what my genius is truly capable of creating...\n\nNow, I must ask that you leave me to my work... there is much to do, and we have little time to waste!" }
quests[44691] = { id = 44691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry Work", description = "We must get Chief Telemancer Oculeth back on his feet as soon as possible.\n\nFind ancient mana, any way you can, and feed it to him.", completion = "Ah, I am feeling much better. Thank you!\n\nNow let us get to work.", objectives = "Use Ancient Mana to feed Chief Telemancer Oculeth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44694] = { id = 44694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Battle at a Time", description = "Before I  became a demon hunter, I practiced the arcane arts. I still retain some of that knowledge, though the fel makes it all but impossible to use.\n\nOne thing I can still manage is the occasional glimpse into faraway places. You've seen me use the nether crucible to do this. I'm afraid that things don't look too good.\n\nThe forces that are arrayed against us are not limited to the Burning Legion. You must act quickly to keep the Broken Isles from being overwhelmed.", completion = "It would seem that you have done an excellent job of eliminating a great many threats on the Broken Isles.\n\nYou never fail to impress me, {name}.", objectives = "Complete 10 World Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44696] = { id = 44696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Daily - Watcher Osu" }
quests[44697] = { id = 44697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Prestige UI - Artifact" }
quests[44698] = { id = 44698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Bit" }
quests[44700] = { id = 44700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormheim", description = "It is good we found you, {name}!\n\nSky Admiral Rogers has sent word for you to meet her in Dalaran. It sounded important. She awaits your presence in the Violet Citadel.\n\nMake haste!", completion = "It's an honor, {name}.", objectives = "Speak to Sky Admiral Rogers at the Violet Citadel in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44701] = { id = 44701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormheim", description = "It is good we found you, {name}!\n\nNathanos Blightcaller, Champion of the Banshee Queen herself, sent for you in Dalaran. He made it sound urgent. He should be waiting for you in the Violet Citadel.\n\nMake haste!", completion = "<Nathanos glances over at you, pausing for a moment before acknowledging your presence.>\n\nYes?", objectives = "Speak to Nathanos Blightcaller at the Violet Citadel in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44702] = { id = 44702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[44703] = { id = 44703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - 7.0 Special - iLevel 750 - 750 - Fox Mount 1" }
quests[44704] = { id = 44704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - 7.0 Special - iLevel 750 - 750 - Fox Mount 2" }
