quests[44706] = { id = 44706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - 7.0 Special - iLevel 750 - 750 - Fox Mount 4" }
quests[44707] = { id = 44707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual of Doom" }
quests[44708] = { id = 44708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual of Doom" }
quests[44719] = { id = 44719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaching the Sanctum", description = "It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area.\n\nTake these telemancy orbs. If you find you need support, use them to summon Withered.\n\nWe must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.", progress = "We've done it! Despite the initial failures, we are still in position to enter the Breach and free our comrades.", completion = "I must commend your knack for overcoming adversity. Take your time gathering your fellow champions, {name}, but don't take TOO long!", objectives = "Speak with Oculeth to start the assault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44720] = { id = 44720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Action", description = "<As the raven stares into your eyes, a familiar voice fills your mind.>\n\nChampion, I require your aid. It seems Helya has shown her hand.\n\nSteel yourself then come to me.", completion = "It is good of you to come.", objectives = "Find Havi at Valdisdall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44721] = { id = 44721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helya's Conquest", description = "If Helya is making an advance on the Broken Isles, we will need to answer in turn.\n\nGo to Tideskorn Harbor and scout her forces. We will see if Helya is foolish enough to begin her campaign against me.", progress = "What is Helya planning?", completion = "She has forced my hand...", objectives = "Search Tideskorn Harbor for evidence of Helya's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44722] = { id = 44722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disillusioned Defector", description = "The atmosphere in the city has improved little, but we may find this to our advantage today.\n\nSilgryn asks for you at the Terrace. It seems even Elisande's forces are fleeing before her insanity.\n\nA defector has risen from the ranks and seeks to join our cause.\n\nSee that this individual is well received, {name}. We need all the friends we can get during these dark times.", completion = "Glad you could make it.", objectives = "Meet Silgryn at Evermoon Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44723] = { id = 44723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Like Me", description = "Greetings, Outlander.\n\nI am Victoire. I served Elisande while she maintained peace in the city. I fought beside demons and worse for the greater good.\n\nThe massacre at the Waning Crescent made it clear that she no longer serves the Nightborne. She serves only herself.\n\nThere are others who feel as I do. They simply need proof that there is another way.\n\nThe Dusk Lily is not unknown to us- try showing it to those now guarding Astravar Harbor. They have seen the worst of Elisande's cruelty.", progress = "Did you find more like me?", completion = "Hopefully more will follow their example.\n\nThank you for showing them another way to serve the Nightborne.", objectives = "Use the Dusk Lily Sigil on Duskwatch Subjugators to identify 5 Deserters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44724] = { id = 44724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Persons", description = "Our new friend brings us some disturbing information.\n\nShe claims to have seen a large number of citizens dragged from Starcaller Retreat in chains. Their destination appears to be Astravar Harbor.\n\nThose taken to the harbor have yet to return, however. Worse yet, the area is now overrun with demons.\n\nI need you to find out where these people went. Infiltrate the harbor and gather any information you can.\n\nStart with the Legion filth- their corpses may point us in the right direction.", progress = "Have you learned where the captives have been taken?", completion = "<Silgryn stares grimly at the communicator.>", objectives = "Acquire a Legion Communicator from demons in Astravar Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44725] = { id = 44725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostage Situation", description = "Our own people, sacrificed to the Legion!\n\nWe need to intercept a transport if we intend to put an end to this trade. I'm afraid this does mean you will be playing the part of a captive, my friend.\n\nBefore voicing your concerns, try to have a little faith.\n\nWe will follow behind in one of Deline's boats and break you out once we know where they are going.\n\nGo to the harbor and find a group of captives. Stand among them. Allow yourself to be taken.\n\nWe will not be far.", progress = "Please try to trust me. We will allow no harm to come to you.", completion = "Thank you for taking this risk. Let us put an end to this now!", objectives = "Go to Astravar Harbor and join a group of captives being taken to Felsoul Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44726] = { id = 44726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Business of Souls", description = "We will hold our position here while you find and slay the demon responsible for this camp.\n\nEnding Aargoss will not permanently stop this smuggling operation, but it may slow them down long enough for us to find another way to help these people.\n\nGo quickly. He is somewhere atop this ridge.", progress = "Have you dealt with Aargoss?", completion = "Well done. Let us leave before they call in reinforcements.", objectives = "Slay Aargoss in Felsoul Advance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44727] = { id = 44727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smuggled!", description = "Please get me out of here!\n\nThe bars are brittle but I am so weak...\n\nThe others! There are so many others! Please help us!", completion = "Thank you. We had no hope of rescue before you came along.", objectives = "Release Maribeth and 5 captives in Felsoul Advance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44728] = { id = 44728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME" }
quests[44729] = { id = 44729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of Valor: Odyn's Favor", description = "The time to deal with that treacherous witch has come. I suspect you may be the one to deal the final blow, but I must be certain.\n\nSee me in the Halls of Valor and we will test the strength of your will.", completion = "Now a greater task awaits you.", objectives = "Gain Odyn's favor within the Trial of Valor Raid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44730] = { id = 44730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravaged Dreams" }
quests[44731] = { id = 44731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitewater Wash Treasure" }
quests[44732] = { id = 44732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgalash" }
quests[44733] = { id = 44733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Corruption", description = "The time has come at last.\n\nDeep within the cavernous underbelly of Karazhan lies a long-forgotten chamber. Based on what you learned from our demon friend, I believe this is where its mistress dwells.\n\nThis demon's master must come from the highest ranks of the Burning Legion. This does not bode well for Karazhan.\n\nWe need to secure Deadwind Pass, {name}.\n\nYou must find this demon and destroy it.", progress = "The threat must be removed.", completion = "Our worst fears have been proven true, {name}. The Legion's presence is deeply rooted in the tower.\n\nThe time has come. We must take back Karazhan!", objectives = "Use the disguise to gain access to the chamber, then slay Thar'zul and Elux'ara Darkscorn beneath Karazhan in Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44734] = { id = 44734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of the Past", description = "Though your primary objective is to liberate the tower from the Legion's hold, I have... another request.\n\nKarazhan is a place where magic and history intertwine. Moments of the past have been known to take physical form, and these forms can possess great power.\n\nAs you journey through Karazhan, watch for places where memories coalesce. These fragments could provide valuable insight into what's really going on inside that tower.", progress = "Have you recovered the fragments?", completion = "For so long the secrets of the tower have remained hidden... I feel as if I have learned more about my former master.\n\nI am greatful we were able to see this journey through together, {name}.", objectives = "Collect the Soul Fragments from the Guest Chambers, Banquet Hall, Servant Quarters, Opera Hall and the Menagerie inside Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44735] = { id = 44735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan: In the Eye of the Beholder", description = "The Legion's intentions are clear. They intend to harness the tower's magical energy to communicate with other Legion worlds!\n\nI'm afraid we haven't much time, {name}. You must ascend the tower and destroy this monstrosity before it is too late!", progress = "The tower must be restored.", completion = "Your efforts today will not be forgotten, {name}.\n\nThough the Legion's presence has left its mark on the Karazhan we once knew, I am certain the fate of the tower will not disappoint.", objectives = "Defeat Viz'aduum the Watcher in Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44736] = { id = 44736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gates of the Nighthold", description = "Our combined armies are arrayed in front of the palace, ready to strike! I cannot believe the time has come.\n\nYour allied commanders are already there and we will join you. Make your way to Astravar Harbor and speak with Khadgar. He is coordinating the attack, or at least I think he is.\n\nSee you there... and thanks for everything.", progress = "Well, that was... unexpected.", completion = "Thank you for saving me. It seems we underestimated Elisande's power.", objectives = "Go to Astravar Harbor and begin the siege of Nighthold with the elves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44737] = { id = 44737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helarjar Landing: Grey Shoals" }
quests[44738] = { id = 44738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full Might of the Elves", description = "Thalyssra managed to get all 3 to agree to the same thing? I am impressed with her skills of negotiation.\n\nAlright hero, Liadrin is already marching on Suramar. Join her forces.\n\nTyrande will flank the city defenders and meet you deeper in.\n\nThe Nightborne will bring up the rear and hold the territory for us.\n\nOculeth and I will move the Kirin Tor forces to Astravar Harbor. With luck, we shall see you on the other side.", progress = "All this running is exhausting.", completion = "The telemancy traps you placed prior to the battle are doing wonders for reducing our losses.", objectives = "Lead the elven army to Astravar Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44739] = { id = 44739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready for Battle", description = "Thanks to your efforts and a lot of effort on the part of our new army, the Nightfallen are prepared for battle.\n\nWhat is more, we have managed to evacuate nearly all of the civilians between here and Astravar Harbor.\n\nI have drafted plans that can lead our combined forces through the city and take the harbor.\n\nCan you deliver these plans to Vereesa, Tyrande and Liadrin?", progress = "So many different types of elves. Each of us changed in some way by the magic we wield. It is very, enlightening.", completion = "Well, with these plans and a little luck, we might be able to get through this with far less collateral damage than I would have expected.", objectives = "Deliver plans to Vereesa Windrunner, Lady Liadrin and Tyrande Whisperwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44740] = { id = 44740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staging Point", description = "That is quite a corridor you and our allies have punched through the city. It will be difficult to hold but it will cut a wedge in Elisande's forces.\n\nOculeth has been busy redirecting a telemancy beacon to this location but wanted to give you the honor of activating it.", progress = "Has the beacon been activated.", completion = "Well done, hero. With this as our staging ground, our forces have a clear shot at the city gates.\n\nThalyssra has ordered her rebels to secure our location and cover our rear flank.\n\nOnce we have our siege vehicles in place we should be ready to assault the city.", objectives = "Activate the Astravar Beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44741] = { id = 44741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan: The Big Bag Theory", description = "I'm sure you've heard, {name}, that a bigger bag is always better. I disagree. I believe it's the quality of the bag that makes all the difference.\n\nJust look at those tattered things around your person. They make you look... well, quite plain.\n\nI'll prove it to you. Allegedly there are some bags in Karazhan that hold an almost infinite amount of items, but the materials required to make such bags are... well, you'll see.", progress = "After this lesson, I trust I won't have to prove anything further to you.", completion = "Now, look closely.\n\n<Tytallo goes into a lengthy explanation concerning the thread count, weaving techniques, and other miscellaneous details that, to a tailor, are fascinating.>\n\nYou still seem confused. Here, take the pattern and see for yourself. Perhaps then you'll learn a thing or two.", objectives = "Recover a Bag of a Thousand Pockets and a Fel Sinew Bag from Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44742] = { id = 44742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tavernkeeper's Fate", description = "I have finished unraveling Ly'leth's message.\n\nI want you to come with me to her estate. It is long past time I returned to the city.", progress = "Dire news like this cannot wait.", completion = "We need to take action immediately!", objectives = "Follow Thalyssra to the Lunastre Estate and learn of Vanthir's fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44743] = { id = 44743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrande's Command", description = "Shal'aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered.\n\nAnd in all of this, Tyrande has a battery of requests I simply do not have the time to deal with.\n\nWill you go to her? Her growing army is hard to miss in Meredil.", completion = "The Nightfallen insisted on being a part in this conflict. There is more work to be done than people we have.", objectives = "Speak with Tyrande Whisperwind in Meredil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44744] = { id = 44744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifelines" }
quests[44746] = { id = 44746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helarjar Landing: Rockaway Coast" }
quests[44748] = { id = 44748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winged Terrors" }
quests[44751] = { id = 44751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Soldier Left Behind" }
quests[44752] = { id = 44752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence Triangulation", description = "Vanthir... an example! That certainly explains why Elisande chose to hold him this long.\n\nWe need to move quickly. I can track him, but I will need to find places where his Arcane Essence is strongest.\n\nThis will not be an easy feat, not in a city this old, but with any luck there are a few places important enough to him that he left a little bit of himself behind.\n\nWe should start in the promenade- he often visited it for business.", progress = "Did you find them?", completion = "All that remains is to focus on his essence to isolate his location. Good work.", objectives = "Help Thalyssra collect 3 of Vanthir's Arcane Essences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44753] = { id = 44753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Public Display", description = "Now that I have identified Vanthir's essence from the multitude of Suramar's citizens, it may be that I can find his exact location.\n\nI believe you'll recall a similar ritual with our friend Theryn. Do not worry- there will be less screaming this time. Hopefully.\n\nCome. Let us find our missing tavernkeeper.", progress = "I need to maintain complete focus.", completion = "That was... difficult... but I am glad we succeeded.", objectives = "Help Thalyssra complete the Scrying Ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44754] = { id = 44754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waxing Crescent", description = "His captor is familiar to me. He is one of Aluriel's lieutenants and a skilled spell-fencer at that. You will need Silgryn's help to retrieve the key to Vanthir's prison.\n\nOur friend's life hangs in the balance. Even if we manage to wrestle him from the executioner's grasp, he may well Wither before we can act.\n\nI need you to take an Arcan'dor fruit to him. They are precious, and few, but for Vanthir this is the only chance he has.\n\nGo quickly, and good luck.", progress = "<Vanthir shudders violently and stares blankly ahead. He does not seem to be aware of your presence.>", completion = "<Vanthir's hands dart up to snatch the fruit from your grasp.>", objectives = "Rescue Vanthir and give him an Arcan'dor fruit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44756] = { id = 44756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sign of the Dusk Lily", description = "Simply... astounding.\n\nI have not felt this clear of mind in so long.\n\nI am still weak... I need to rest. But first...\n\n<Vanthir gestures to the top of his cage with a trembling hand.>\n\nShow them that the Dusk Lily triumphs this day.", completion = "I will see that he is made comfortable next chance I get. We made a great stride forward today, {name}.\n\nElisande will not soon forget that we do not simply abandon our own.", objectives = "Place a Dusk Lily Sigil above Vanthir's Cage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44758] = { id = 44758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's the Cache?", description = "We're here for a cache of gunpowder. It seems to have been infused with some sort of fel power... it's extremely reactive. One of the leaders of the pirate forces here currently has it.\n\nMaster Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.", progress = "Did you get the gunpowder?", completion = "This gunpowder is the key to my plan. Right good work retrieving it.", objectives = "Kill Master Gunner Prix and obtain the Fel-Infused Gunpowder Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44759] = { id = 44759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vale of Dread" }
quests[44760] = { id = 44760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood On Your Hands", objectives = "Around the isles, the very blood of our enemy attempts to corrupt all things. But as you may already know, this blood can be extracted.\n\nWe demon hunters use this blood for our own rituals, fueling us to fight back the demon invasion.\n\nBring me any Blood of Sargeras you find and I will trade with you what I can.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44761] = { id = 44761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Runebound Scroll" }
quests[44764] = { id = 44764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon in Disguise", description = "While you were... working your magic on that demon, I was able to make headway in distilling the corrupted essences down to a simpler, more manageable form.\n\nI've asked Khadgar to provide you with the concoction once he's had a look, but I must remind you - these essences are quite potent, often dangerous if not handled with the utmost of care.\n\nSpeak with Khadgar when you are ready to begin.", completion = "The samples have proven to be quite helpful along with your... influence.", objectives = "Speak with Archmage Khadgar in Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44765] = { id = 44765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranglethorn Fishing Extravaganza", progress = "Any bites?", completion = "You'd better hurry up and hand over the fish if you want to win!" }
quests[44766] = { id = 44766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backup Plan", description = "Dalaran may appear to be just a floating city, but it is actually our most powerful magical weapon. It will take time to repair the arcane defenses - time the Legion will use to their great advantage.\n\nIt is imperative to come up with an interim plan, and quickly! \n\nArchmage Kalec is very knowledgeable about this sort of thing. Perhaps you should consult with him?", completion = "Hmm. An interesting challenge!", objectives = "Speak with Archmage Kalec.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44767] = { id = 44767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Celestial Invitation", description = "Greetings, mortal.\n\nFor many years I have continued my observation of this planet. The halls of Ulduar have been hollow and silent, save for the occasional clattering whisper from the darkness. I grew so very bored of it!\n\nThus, I have taken up this \"pet battling\" you seem so fond of. Truly, an amusing pastime that will sustain my mind for many centuries!\n\nI have been amassing my collection, scouring the stars for tiny beings of cosmic power. Come, let us do battle once more!", progress = "Greetings, mortal. Do you wish to engage in a battle of the tiny minions?", completion = "Ah, quite the breath of fresh solar winds. Take this, my favorite constellation, may it remind you of the watchers that watch over us all.", objectives = "Defeat Algalon the Observer in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44768] = { id = 44768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nyell's Workshop", description = "From what I've overheard, this is Master Artificer Nyell's workshop. His skills in construct creation are unparalleled! \n\nWhat a shame that he swore fealty to the Legion. I hate to destroy such a renowned craftsman, but we have no choice.\n\nIf you are lucky, he might even have a spare shield generator sitting around.", progress = "Were you successful?", completion = "That is one less Legion supporter we need to worry about. Oh, and you found a shield generator too? Wonderful!", objectives = "Kill Master Artificer Nyell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44769] = { id = 44769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arming the Populace" }
quests[44770] = { id = 44770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Shal'dorei", description = "This workshop includes an extensive library of rare scrolls written by my people. We all benefit by sharing information, do you not agree? \n\nPerhaps if we bring back such a treasure trove the Tirisgarde will be more welcoming towards me and my kind...\n\nPlease gather whatever you can.", progress = "Have you found some scrolls?", completion = "Few texts written by the ancient shal'dorei remain. I am sure the Tirisgarde's librarians will be thrilled with these!", objectives = "Gather 8 Ancient Shal'dorei Scrolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44771] = { id = 44771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Threat Rises", description = "It is time I told you another tale. While you listen, would you be so kind as to pour me some grog? I've grown a terrible thirst.\n\nThe keg is very old and the tap is a bit slow.", progress = "I've told you my tale, but did you bring the grog?", completion = "Delicious, thank you.\n\nBefore we act, we must gather more information onto what Helya is planning.", objectives = "Pour Havi some grog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44772] = { id = 44772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ch 5 Available Tracking Quest" }
quests[44775] = { id = 44775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Peak of Bones", description = "While you were gone, we strategized what to do with the harness. We can utilize its power to bind the spirits of deceased drakes to you, raising them under your will as loyal soldiers.\n\nI sent Minerva to Thorim's Peak in Stormheim, where she has found a brood of deceased Thorignir. They will be prime targets.\n\nSpeak to Grimwing for a flight to the mountain, then Minerva will fill you in.", completion = "Finally you're here, Deathlord. I've been waiting so long I could've died again.", objectives = "Speak to Grimwing for a flight to Thorim's Peak, then meet Minerva.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44777] = { id = 44777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME" }
quests[44780] = { id = 44780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backlash" }
quests[44781] = { id = 44781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Council's Call", description = "<The Council of Six has sought your aid against a 'great threat'.>\n\n<If they have turned their focus on something outside of the demon hordes pouring out of the Tomb of Sargeras, it must be truly dangerous.>\n\n<But how does the object you found on the Broken Shore fit into all of this? You know only that the Council awaits at the Violet Citadel.>", objectives = "Seek out the Council of Six in the Violet Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44782] = { id = 44782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Away From Prying Eyes", description = "Wars are not won solely with armies charging bravely across the battlefield, {class}t.\n\nSometimes, it is the actions of individuals that matter most, fighting battles few ever hear about. That is why - \n\n<Khadgar furrows his brow slightly.>\n\nWe should really discuss this somewhere a tad more private. Let's move up to the Purple Parlor, shall we?", progress = "We should discuss this matter further in the Purple Parlor just above us.", completion = "Don't worry, she'll be alright.\n\nWhatever demon did this to her didn't hang around long enough to finish the job.", objectives = "Join the Council of Six in the Purple Parlor above the Violet Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44783] = { id = 44783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Bones They Rise", description = "Alright, the job is to get the broodmother under our control. But hear me out. A few more drakes would be a boon, right?\n\nWhile we're here, why don't we use our awesome power over undeath to raise some of her brood as well? Although the peak has claimed their corpses for the ice, I'm sure the embrace of undeath will be much more welcoming. We must find their frozen corpses and breathe your will into them.", progress = "Have you granted the drakes their unbirth?", completion = "I could feel their energy, even in undeath.", objectives = "Revive 4 Deceased Thorignir in Thorim's Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44784] = { id = 44784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advanced Wanding" }
quests[44785] = { id = 44785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tea Party", description = "I...I-I'm sorry. I... I can't...\n\n\n<You hear footsteps behind you.>\n\n\nA... Abby? Wh...", completion = "Was that really Abby? Did she bring forth that... thing? We thought her dead not long ago.\n\nWhat could we have done to bring such... such horror upon our village?", objectives = "Find Abby Lewis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44786] = { id = 44786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midterm: Rune Aptitude" }
quests[44787] = { id = 44787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bonemother", description = "It's time to call the mother, the true reason we came. She is strong, her sheer will and strength allowing her to face this peak in order to watch over the remains of her brood. While the Thorignir is a grand sight, I like my dragons a little more bony. She must die first.\n\nRemember the pyre where we met? She is its guardian, as the spirit was at the peak. If we light it, she will come.", completion = "That was quite the entrance, Deathlord.", objectives = "Light Thorim's Beacon at Thorim's Peak to raise Daumyr. Defeat her and raise her from death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44788] = { id = 44788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Study: Bestiaries of Azsuna" }
quests[44789] = { id = 44789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holding the Ramparts", description = "With their ground presence weakened the Legion has retaliated with additional forces.\n\nOur allies managed to track several of these demons to the skies above Black Rook. I fear they intend to establish a foothold.\n\nTake this hippogryph and scout the ramparts. Should this fear become a reality I ask that you deal with the threat swiftly.", progress = "Any word?", completion = "Our victory here is well deserved. With their forces subdued we can press our attacks to the forward camp and the monstrosity on the horizon.", objectives = "Scout the demonic presence atop Black Rook Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44790] = { id = 44790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial by Demonfire", description = "We are out of time. I have reports that a pitlord has come to Meredil. \n\nI have dispatched a strike force. We cannot let this demon flank our army here, nor can we let him find Shal'Aran. It is time to temper these recruits in a real battle.\n\nJoin our forces in Meredil, engage the demon, and help us ensure this new army of ours is not lost in its first conflict.", completion = "Well done. Sometimes a single victory is enough to bring an army together. With time, these recruits shall train others, and we can grow our army to many times this size.", objectives = "Slay Rozzeleth in Meredil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44799] = { id = 44799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safe Keeping" }
quests[44800] = { id = 44800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Magatha's Will", description = "Well? What are you waiting for? Hand over the Doomstone.", completion = "The Doomstone! I thought it legend, but here it is before me\n\nCan you feel its power radiating? We must only use it in times of utmost need; its power has a heavy price.\n\nYou were right not to give it to Magatha. It could do much harm in her hands.\n\nI trust you to keep it safe while we prepare an appropriate home for it.", objectives = "Talk to Magatha Grimtotem, then bring the Doomstone to Farseer Nobundo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44801] = { id = 44801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending Shal'aran" }
quests[44802] = { id = 44802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Guidance" }
quests[44803] = { id = 44803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan: Master of the House", description = "Inside the pocket watch is a worn note.\n\n\"The next affair will take place in Morgan's Plot, it will cause quite a stir! The following guests will be in attendance:\n\nLord Ference, his preferred vintage is red.\nBaroness Millstipe, she will only attend on the promise of cheese. Strange woman.\nBaron Dreuger, a ravenous soul, any well spiced meat should keep him happy.\n\nAs always, I shall ring the bell should I need you.\n\n- Medivh\"", progress = "What do you have there?", completion = "Wonderful, you brought dinner! Moroes was worried he would let his master down.", objectives = "Collect the listed items and bring them to the cemetery outside Karazhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44805] = { id = 44805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Thick of It" }
